/* The tables of M28 · Payroll. */

export const salaryComponents = defineTable(
  'salary_components',
  { module: 'M28', scope: 'org' },
  {
    ...baseColumns,
    /** "Basic pay", "House rent allowance" */
    name: text().notNull(),
    nameUr: text(),
    code: text().notNull(),
    kind: enumText(salaryComponentKinds).notNull(),
    /** `system` components are computed by a rule, never typed */
    calc: enumText(salaryComponentCalcs).notNull(),
    /** required for `system` */
    systemKey: enumText(salaryComponentSystemKeys),
    /** for earnings */
    isTaxable: boolean().notNull().default(true),
    /** for earnings */
    inGross: boolean().notNull().default(true),
    /** reduced for days not worked */
    prorate: boolean().notNull().default(true),
    sortOrder: integer().notNull().default(0),
    /** falls back to the mapping */
    expenseAccountId: uuid().references((): AnyPgColumn => accounts.id),
    isActive: boolean().notNull().default(true),
  },
  (t) => [
    check(
      'salary_components_system_key_needed',
      sql`${t.calc} <> 'system' or ${t.systemKey} is not null`,
    ),
    uniqueIndex('salary_components_name_uq').on(t.orgId, t.name).where(live(t)),
    uniqueIndex('salary_components_code_uq').on(t.orgId, t.code).where(live(t)),
  ],
);

/** What one person is paid from a date. */
export const salaryStructures = defineTable(
  'salary_structures',
  { module: 'M28', scope: 'org', cap: 'payroll', capOwner: 'staffId' },
  {
    ...baseColumns,
    staffId: uuid()
      .references((): AnyPgColumn => staff.id)
      .notNull(),
    effectiveFrom: dateStr().notNull(),
    effectiveTo: dateStr(),
    basic: paisa().notNull(),
    /** computed from its items */
    gross: paisa().notNull(),
    reason: enumText(salaryStructureReasons).notNull(),
    status: enumText(salaryStructureStatuses).notNull().default('draft'),
    approvalRequestId: uuid().references((): AnyPgColumn => approvalRequests.id),
    incrementId: uuid().references((): AnyPgColumn => increments.id),
  },
  (t) => [
    check('salary_structures_effective_from_first', sql`extract(day from ${t.effectiveFrom}) = 1`),
    positive('salary_structures', t.basic),
    nonNegative('salary_structures', t.gross),
  ],
);

export const salaryStructureItems = defineTable(
  'salary_structure_items',
  { module: 'M28', scope: 'org', cap: 'payroll', capOwner: 'staffId' },
  {
    ...baseColumns,
    structureId: uuid()
      .references((): AnyPgColumn => salaryStructures.id)
      .notNull(),
    staffId: uuid()
      .references((): AnyPgColumn => staff.id)
      .notNull(),
    /** a `fixed` or `percent_of_basic` component */
    componentId: uuid()
      .references((): AnyPgColumn => salaryComponents.id)
      .notNull(),
    /** for `fixed` */
    amount: paisa(),
    /** for `percent_of_basic` */
    percent: decimal(6, 3),
  },
  (t) => [
    nonNegative('salary_structure_items', t.amount),
    uniqueIndex('salary_structure_items_structure_component_uq')
      .on(t.structureId, t.componentId)
      .where(live(t)),
  ],
);

export const increments = defineTable(
  'increments',
  { module: 'M28', scope: 'org', cap: 'payroll', capOwner: 'staffId' },
  {
    ...baseColumns,
    staffId: uuid()
      .references((): AnyPgColumn => staff.id)
      .notNull(),
    kind: enumText(incrementKinds).notNull(),
    effectiveFrom: dateStr().notNull(),
    oldGross: paisa().notNull(),
    newGross: paisa().notNull(),
    /** generated */
    percent: decimal(6, 2).generatedAlwaysAs(
      (): SQL =>
        sql`case when ${increments.oldGross} > 0 then round((${increments.newGross} - ${increments.oldGross}) * 100.0 / ${increments.oldGross}, 2) end`,
    ),
    /** groups a yearly round */
    batchRef: text(),
    status: enumText(incrementStatuses).notNull().default('proposed'),
    approvalRequestId: uuid().references((): AnyPgColumn => approvalRequests.id),
    note: text(),
  },
  (t) => [
    check('increments_effective_from_first', sql`extract(day from ${t.effectiveFrom}) = 1`),
    nonNegative('increments', t.oldGross),
    positive('increments', t.newGross),
  ],
);

export const payrollRuns = defineTable(
  'payroll_runs',
  { module: 'M28', scope: 'branch', cap: 'payroll' },
  {
    ...baseColumns,
    branchId: branchIdColumn(),
    /** from the `payroll_run` sequence */
    runNo: text().notNull(),
    kind: enumText(payrollRunKinds).notNull().default('regular'),
    payMonth: dateStr().notNull(),
    /** the attendance period */
    periodFrom: dateStr().notNull(),
    periodTo: dateStr().notNull(),
    payDate: dateStr().notNull(),
    status: enumText(payrollRunStatuses).notNull().default('draft'),
    staffCount: integer().notNull().default(0),
    grossTotal: paisa().notNull().default(0),
    deductionsTotal: paisa().notNull().default(0),
    netTotal: paisa().notNull().default(0),
    employerCostTotal: paisa().notNull().default(0),
    warnings: jsonb().notNull().default([]),
    calculatedAt: timestamptz(),
    approvalRequestId: uuid().references((): AnyPgColumn => approvalRequests.id),
    approvedAt: timestamptz(),
  },
  (t) => [
    check('payroll_runs_pay_month_first', sql`extract(day from ${t.payMonth}) = 1`),
    nonNegative('payroll_runs', t.grossTotal),
    nonNegative('payroll_runs', t.deductionsTotal),
    nonNegative('payroll_runs', t.netTotal),
    nonNegative('payroll_runs', t.employerCostTotal),
    uniqueIndex('payroll_runs_branch_pay_month_uq')
      .on(t.branchId, t.payMonth)
      .where(sql`${t.deletedAt} is null and ${t.kind} = 'regular' and ${t.status} <> 'cancelled'`),
  ],
);

export const payslips = defineTable(
  'payslips',
  { module: 'M28', scope: 'branch', cap: 'payroll', capOwner: 'staffId' },
  {
    ...baseColumns,
    branchId: branchIdColumn(),
    runId: uuid()
      .references((): AnyPgColumn => payrollRuns.id)
      .notNull(),
    staffId: uuid()
      .references((): AnyPgColumn => staff.id)
      .notNull(),
    payMonth: dateStr().notNull(),
    /** empty for a settlement-only slip */
    structureId: uuid().references((): AnyPgColumn => salaryStructures.id),
    daysInPeriod: decimal(5, 1).notNull(),
    paidDays: decimal(5, 1).notNull(),
    absentDays: decimal(5, 1).notNull().default(0),
    unpaidLeaveDays: decimal(5, 1).notNull().default(0),
    lateHalfDays: decimal(5, 1).notNull().default(0),
    earnings: paisa().notNull(),
    deductions: paisa().notNull(),
    /** `earnings - deductions`; never negative */
    net: paisa().notNull(),
    employerContributions: paisa().notNull().default(0),
    taxableThisMonth: paisa().notNull().default(0),
    /** tax year to date, including this slip */
    taxableToDate: paisa().notNull().default(0),
    taxToDate: paisa().notNull().default(0),
    payMethod: enumText(payslipPayMethods).notNull(),
    /** copied when calculated */
    bankTitle: text(),
    bankIban: text(),
    status: enumText(payslipStatuses).notNull().default('draft'),
    holdReason: text(),
    paidOn: dateStr(),
    paymentReference: text(),
    /** visible to the staff member */
    isPublished: boolean().notNull().default(false),
    documentId: uuid().references((): AnyPgColumn => generatedDocuments.id),
  },
  (t) => [
    nonNegative('payslips', t.earnings),
    nonNegative('payslips', t.deductions),
    nonNegative('payslips', t.net),
    nonNegative('payslips', t.employerContributions),
    nonNegative('payslips', t.taxableThisMonth),
    nonNegative('payslips', t.taxableToDate),
    nonNegative('payslips', t.taxToDate),
    uniqueIndex('payslips_run_staff_uq').on(t.runId, t.staffId).where(live(t)),
    index('payslips_staff_pay_month_idx').on(t.orgId, t.staffId, t.payMonth),
  ],
);

