/** A loan repaid over several months, or an advance recovered from the next salary. */
export const staffLoans = defineTable(
  'staff_loans',
  { module: 'M28', scope: 'org', cap: 'payroll', capOwner: 'staffId' },
  {
    ...baseColumns,
    /** from the `staff_loan` sequence */
    loanNo: text().notNull(),
    staffId: uuid()
      .references((): AnyPgColumn => staff.id)
      .notNull(),
    kind: enumText(staffLoanKinds).notNull(),
    principal: paisa().notNull(),
    reason: text().notNull(),
    /** 1 for an advance */
    instalmentCount: integer().notNull(),
    firstDeductionMonth: dateStr().notNull(),
    /** maintained with each instalment */
    outstanding: paisa().notNull(),
    status: enumText(staffLoanStatuses).notNull().default('requested'),
    approvalRequestId: uuid().references((): AnyPgColumn => approvalRequests.id),
    disbursedOn: dateStr(),
    disbursedFrom: enumText(staffLoanDisbursedFromOptions),
    bankAccountId: uuid().references((): AnyPgColumn => bankAccounts.id),
    requestedBy: uuid()
      .references((): AnyPgColumn => profiles.id)
      .notNull(),
  },
  (t) => [positive('staff_loans', t.principal), nonNegative('staff_loans', t.outstanding)],
);

